// src/pages/client/MySchedule.js
import React, { useState, useEffect } from 'react';
import { loansAPI } from '../../services/api';
import { Calendar, CheckCircle, Clock, AlertCircle } from 'lucide-react';

const fmtMoney = (n) => new Intl.NumberFormat('en-US').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US', { day: '2-digit', month: 'long', year: 'numeric' }) : '—';

export default function MySchedule() {
  const [loans, setLoans] = useState([]);
  const [selectedLoan, setSelectedLoan] = useState('');
  const [schedule, setSchedule] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loansAPI.getMyLoan()
      .then(r => { setLoans(r.data.data); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  const handleSelect = async (id) => {
    setSelectedLoan(id);
    if (!id) return;
    try {
      const r = await loansAPI.getSchedule(id);
      setSchedule(r.data.data);
    } catch {}
  };

  useEffect(() => {
    if (loans.length === 1 && !selectedLoan) {
      handleSelect(loans[0]._id);
    }
  }, [loans, selectedLoan]);

  const paid = schedule.filter(s => s.status === 'PAID').length;
  const overdue = schedule.filter(s => s.status === 'OVERDUE').length;
  const pending = schedule.filter(s => s.status === 'PENDING').length;

  if (loading) return <div className="page-loader"><div className="spinner" style={{ width: 32, height: 32 }} /></div>;

  return (
    <div className="fade-in">
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 22, marginBottom: 4 }}>Repayment Schedule</h1>
        <p style={{ color: 'var(--gray-500)', fontSize: 13 }}>Track your monthly installments</p>
      </div>

      {loans.length === 0 ? (
        <div className="card" style={{ padding: 48, textAlign: 'center' }}>
          <Calendar size={40} style={{ opacity: 0.3, marginBottom: 12 }} />
          <p style={{ color: 'var(--gray-400)' }}>No loans available</p>
        </div>
      ) : (
        <>
          {loans.length > 1 && (
            <div className="card" style={{ padding: '14px 18px', marginBottom: 16 }}>
              <select className="form-control" style={{ maxWidth: 360 }} value={selectedLoan} onChange={e => handleSelect(e.target.value)}>
                <option value="">Select a loan...</option>
                {loans.map(l => <option key={l._id} value={l._id}>{fmtMoney(l.amount)} — {l.status}</option>)}
              </select>
            </div>
          )}

          {schedule.length > 0 && (
            <>
              {/* Stats */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 14, marginBottom: 20 }}>
                {[
                  { label: 'Paid', count: paid, icon: CheckCircle, color: 'var(--success)', bg: 'var(--success-light)' },
                  { label: 'Pending', count: pending, icon: Clock, color: 'var(--warning)', bg: 'var(--warning-light)' },
                  { label: 'Overdue', count: overdue, icon: AlertCircle, color: 'var(--danger)', bg: 'var(--danger-light)' },
                ].map(({ label, count, icon: Icon, color, bg }) => (
                  <div key={label} className="stat-card" style={{ padding: 16 }}>
                    <div className="stat-icon" style={{ background: bg, width: 36, height: 36 }}>
                      <Icon size={16} color={color} />
                    </div>
                    <div className="stat-value" style={{ fontSize: 28, color }}>{count}</div>
                    <div className="stat-label">{label}</div>
                  </div>
                ))}
              </div>

              {/* Schedule table */}
              <div className="card">
                <div style={{ padding: '14px 18px', borderBottom: '1px solid var(--gray-100)' }}>
                  <h3 style={{ fontSize: 14 }}>Details of {schedule.length} installments</h3>
                </div>
                <div className="table-wrap">
                  <table>
                    <thead>
                      <tr>
                        <th>Month</th>
                        <th>Amount Due</th>
                        <th>Due Date</th>
                        <th>Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {schedule.map(s => (
                        <tr key={s._id} style={{ background: s.status === 'OVERDUE' ? '#fff5f5' : s.status === 'PAID' ? '#f0fff4' : 'transparent' }}>
                          <td>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              <div style={{
                                width: 26, height: 26, borderRadius: '50%',
                                background: s.status === 'PAID' ? 'var(--success-light)' : s.status === 'OVERDUE' ? 'var(--danger-light)' : 'var(--gray-100)',
                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                fontSize: 11, fontWeight: 700,
                                color: s.status === 'PAID' ? 'var(--success)' : s.status === 'OVERDUE' ? 'var(--danger)' : 'var(--gray-500)',
                              }}>{s.monthNumber}</div>
                              <span style={{ fontWeight: 500 }}>Month {s.monthNumber}</span>
                            </div>
                          </td>
                          <td style={{ fontWeight: 600 }}>{fmtMoney(s.amountDue)}</td>
                          <td style={{ color: s.status === 'OVERDUE' ? 'var(--danger)' : 'var(--gray-600)' }}>{fmtDate(s.dueDate)}</td>
                          <td>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                              {s.status === 'PAID' && <CheckCircle size={13} color="var(--success)" />}
                              {s.status === 'OVERDUE' && <AlertCircle size={13} color="var(--danger)" />}
                              {s.status === 'PENDING' && <Clock size={13} color="var(--warning)" />}
                              <span className={`badge ${s.status === 'PAID' ? 'badge-success' : s.status === 'OVERDUE' ? 'badge-danger' : 'badge-warning'}`}>
                                {s.status === 'PAID' ? 'Paid' : s.status === 'OVERDUE' ? 'Overdue' : 'Pending'}
                              </span>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          )}

          {loans.length === 1 && schedule.length === 0 && (
            <div className="card" style={{ padding: 48, textAlign: 'center' }}>
              <Calendar size={40} style={{ opacity: 0.3, marginBottom: 12 }} />
              <p style={{ color: 'var(--gray-400)' }}>Loading schedule...</p>
            </div>
          )}
        </>
      )}
    </div>
  );
}
